  "왜": "일이 바뀌었다고 하셨죠. 요 몇 해 이 사람한테는 일이 서는 운이 없어서, 이번 변화는 운이 아니라 이 사람이 스스로 한 거예요. 지키던 돈을 거기 넣었을 거예요. 그래서 요즘 덜 쓰는 건 없어서가 아니라 다 들어가 있어서예요. 운이 안 받쳐 주는 일이라 흔들릴 수 있고, 그때 옆에 있어 준 사람한테 이 사람 돈이 나중에 제일 크게 가요. 오늘은 새 일이 어떤지 묻고 이번엔 공주님이 사세요."
