  "왜": "연락이 길어지고 안 하던 말을 한다고 하셨죠. 요 몇 해 이 사람한테 들어온 건 여자·돈의 운이라, 마음이 생기면 만나자는 약속과 돈 쓰는 걸로 나오는데 그 앞에 말이 먼저 새어 나온 거예요. 원래 좋아하면 표정부터 달라지는 사람이라 평소에도 티는 났을 텐데, 요즘은 그 티가 평소보다 좀 더 넘쳐서 말로까지 나온 거예요. 운이 가면 밥값 내고 주말 비우는 건 평소 크기로 돌아가지만 마음까지 같이 가진 않아요. 오늘 이 사람이 한 말 중 하나를 골라 언제 할 거냐고 물어보세요. 날짜가 나오면 이미 온 거예요."
