  "왜": "새 일을 시작했다고 하셨죠. 요 몇 해 이 사람 운은 일이 열리는 운이 아니라서, 직장을 옮기거나 새로 맡았다면 운이 열어 준 게 아니라 이 사람이 스스로 판을 바꾼 거예요. 안으로 품는 사람이 밖으로 뭘 바꿨다는 건 속에서 오래 쌓인 게 터진 거라 지금은 그쪽에 온 힘이 가 있어요. 마음은 있는데 순번이 밀려 있는 거예요. 운이 받쳐 주지 않는 변화라 이 사람 혼자 버거워요. 그래서 지금은 공주님이 앞에서 당겨야 하고, 옆에서 힘이 되어 주는 사람이 이 사람 눈에 제일 먼저 들어와요. 오늘은 잘하고 있다고 한마디만 해 주세요."
