  "왜": "일이 먼저 바뀌었다고 하셨죠. 이 사람은 원래 먼저 사는 사람인데, 요 몇 해 여자·돈의 운이 들어오면서 돈이 움직였고 그 돈이 먼저 직장을 바꿨어요. 이 사람한테 돈은 사람한테 쓰는 건데 지금은 그 돈을 만드는 중이에요. 그래서 요즘 덜 산다면 아끼는 게 아니라 순서예요. 일이 자리 잡으면 그 손이 공주님한테 와요. 운이 가면 벌이는 평소로 돌아가도 사 주는 손은 남아요. 오늘은 새 일이 어떤지 물어보세요. 첫 월급 얘기가 나오면 그 다음이 공주님이에요."
