  "왜": "먼저 다가오고 씀씀이가 달라졌다고 하셨죠. 요 몇 해 이 사람한테는 돈도 말도 일도 특별한 운이 없어요. 그런데도 사 주고 다가온다면 운이 시킨 게 아니라 이 사람 원래 손이에요. 좋아하면 먼저 사는 사람이고 지금 좋아하는 거예요. 운이 밀어 주지 않아서 크게 불진 않지만 줄지도 않아요. 이 사람 평소 크기가 지금 보이는 거예요. 오늘은 그냥 편하게 받으세요. 이 사람한테는 그게 제일 좋은 답이에요."
